import "core-js/modules/es.array.push.js";
import axios from 'axios';
export default {
  data() {
    return {
      profileForm: {
        username: '',
        first_name: '',
        last_name: '',
        email: ''
      }
    };
  },
  mounted() {
    this.fetchUserDetails();
  },
  methods: {
    async fetchUserDetails() {
      try {
        const response = await axios.get('users/api/user/profile/');
        this.profileForm = response.data.user_info.reduce((acc, item) => {
          acc[item.label.toLowerCase().replace(' ', '_')] = item.value;
          return acc;
        }, {});
      } catch (error) {
        console.error('Error fetching user details:', error);
      }
    },
    async saveProfile() {
      try {
        await axios.post('/api/user/profile/edit/', this.profileForm);
        this.$router.push('/profile');
      } catch (error) {
        console.error('Error saving profile:', error);
      }
    },
    cancel() {
      this.$router.push('/profile');
    }
  }
};
